output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_pushing_cart_into_single_file_aisle",
    "text": "A shopper must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartEntersSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "singleFileShelfAisle",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntersSingleFileAisle"
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouths",
    "text": "Carts may be put down only at designated wide parking mouths outside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "cartParkingMouth": {
          "and": [
            "wideCrossAisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks a cart at a single-file-aisle mouth, they are obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtMouth": {
          "pre": {
            "and": [
              "cartParkingMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickupCartAtMouth": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtMouth",
      "discharge": "pickupCartAtMouth"
    }
  },
  {
    "id": "cart_required_for_open_shelf_interaction",
    "text": "Shelf interactions outside single-file shelf aisles must be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "openShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfServicePoint",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_travel_only_in_hand_access_zone",
    "text": "After taking a cart, a shopper may be without it only at the entrance/cart rack, a cart-parking mouth, or inside a single-file hand-access aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceOrCartRack": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "singleFileShelfAisle",
            "cartParkingMouth",
            "entranceOrCartRack"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_hand_pick",
    "text": "After picking an item by hand inside a single-file shelf aisle, the shopper must return and pick up the parked cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "handPickInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "pickupCartAtMouth": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "handPickInSingleFileAisle",
      "discharge": "pickupCartAtMouth"
    }
  },
  {
    "id": "leave_single_file_aisle_via_cart_mouth",
    "text": "A shopper leaving a single-file shelf aisle must emerge at a cart-parking mouth rather than elsewhere.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "leaveSingleFileAisleWrongly": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "singleFileShelfAisle"
              },
              {
                "not": "cartParkingMouth"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveSingleFileAisleWrongly"
    }
  }
]
